import {positionPanel} from './position.js';
import { TEMPLATE_WEIGHT_METHOD } from './themes.js';
import { SCALE, units, usd, short, initialAmounts, completeValue } from './finance.js';
import { referenceBasket } from './reference.js';
import { compositionKey, mixSummary } from './basket-radar.js';
import { createRadarUI } from './radar-ui.js';
import { historicalBasket,compareHistorical } from '../shared/market-history.js';
import { ALLOWED } from '../worker/assets.js';

export function createWorkspaceUI(ctx) {
  const { state, saved, themes, esc, btn, badge, icon, save, p } = ctx;
  const colors = ['#dfff56', '#a788da', '#c0c9b7', '#d7c7a9', '#b4c4cc'];
  const navItems = [['discover','Discover'],['radar','Basket Radar'],['portfolio','My portfolio'],['onchain','Onchain baskets'],['watchlist','Watchlist'],['sectors','Sector coverage'],['tokens','Token universe'],['community','Create a basket'],['methodology','Methodology'],['data','Data & network']];
  const tokenName = s => (state.assets.find(a => a.tokenSymbol === s)?.tokenName || s).replace(' • Robinhood Token', '');
  const time = at => new Date(at).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' });
  const basketMark = t => `<span class="set-emblem" aria-hidden="true"><img src="/assets/baskets/${t.iconId||t.id}.png" alt="" width="128" height="128" decoding="async"></span>`;
  const tokenMark = s => `<span class="token-mark ${['SPY','QQQ'].includes(s)?'issuer-mark':''}" aria-hidden="true"><img src="/assets/tokens/${esc(s)}.${s==='SPY'?'svg':'png'}" alt="" width="180" height="180" decoding="async"></span>`;
  const chips = assets => `<div class="asset-chips">${assets.map(s => `<span>${esc(s)}</span>`).join('')}</div>`;
  const allocation = (assets, weights) => `<div class="allocation-track" aria-label="Initial allocation">${assets.map((s,i) => `<span style="--allocation:${Math.max(0,Number(weights[i]) || 0)};--asset-color:${colors[i%colors.length]}" title="${esc(s)} ${esc(weights[i])}%"></span>`).join('')}</div><div class="allocation-key">${assets.map((s,i) => `<span><i style="background:${colors[i%colors.length]}"></i>${esc(s)} <b>${esc(weights[i])}%</b></span>`).join('')}</div>`;
  const empty = (glyph, title, text, action='') => `<div class="workspace-empty"><div class="empty-emblem">${icon(glyph)}</div><div><h3>${title}</h3><p>${text}</p>${action}</div></div>`;
  const stat = (label,value,note='') => `<div><small>${label}</small><strong>${value}</strong>${note?`<span>${note}</span>`:''}</div>`;
  const section = (title,detail='',action='') => `<div class="section-label"><div><h2>${title}</h2>${detail?`<p>${detail}</p>`:''}</div>${action}</div>`;

  const radarUI=createRadarUI({...ctx,colors,basketMark,tokenMark,allocation,reference});
  function reference(t) {
    try {
      saved.references ||= {};
      const key=compositionKey(t), signature=JSON.stringify([t.assets,t.weights]);
      const legacy=saved.references[t.id]?.signature===signature?saved.references[t.id]:null;
      const old=saved.references[key]||legacy;
      const result=referenceBasket(t,old,state.prices);
      if(!saved.references[key]){
        ctx.observations()['theme:'+key]=old===result.base&&legacy?(ctx.observations()['theme:'+t.id]||[]):[];
      }
      saved.references[key]=result.base;
      if(old!==result.base)ctx.observations()['theme:'+key]=[];
      save();ctx.recordObservation('theme:'+key,result.value);
      return {...result,key};
    } catch { return null; }
  }

  function shell(body) {
    const route = ctx.route(), fresh = Object.values(state.prices).filter(x => x.ok).length;
    const active = id => route === id || id === 'discover' && route.startsWith('theme/') || id === 'onchain' && (route.startsWith('basket/')||route.startsWith('fund/')||route.startsWith('exit/'));
    const title = navItems.find(([id]) => id === route)?.[1] || (route.startsWith('exit/')?'Sell basket':route.startsWith('fund/')?'Buy basket':route.startsWith('theme/')?'Allocation detail':'Basket detail');
    const navigation = navItems.map(([id,label],i) => `${id==='methodology'?'<div class="nav-label">THE DETAILS</div>':''}<a class="nav-item ${active(id)?'active':''}" ${active(id)?'aria-current="page"':''} href="#${id}">${icon(id==='radar'?'sectors':id)}<span>${label}</span>${id==='watchlist'?`<b class="nav-count">${saved.watch.length}</b>`:''}</a>`).join('');
    return `<button class="skip-link" data-action="skip-content">Skip to content</button><aside id="site-navigation" class="sidebar ${state.nav?'expanded':''}"><a class="brand" href="#discover">${ctx.mark}<span class="brand-word">HOODSET<span class="brand-period">.</span><small>SETS ON ROBINHOOD CHAIN</small></span></a><button class="mobile-nav-search" data-action="search">${icon('search')}<span>Search HOODSET</span><kbd>/</kbd></button><div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation">${navigation}</nav><div class="sidebar-note"><span>YOUR THESIS.<br>YOUR SIGNATURE.</span><p>Fixed composition.<br>Transparent backing.</p><a href="#methodology">How a share works</a></div><a class="network" href="#data"><span class="network-icon">${icon('network')}</span><div>Robinhood Chain<small>MAINNET 4663 / ETH GAS</small></div></a></aside>${state.nav?btn('Close navigation','menu','nav-scrim','aria-label="Close navigation"'):''}<div class="workspace"><header class="topbar">${btn(icon('menu'),'menu','mobile-menu',`aria-label="Toggle navigation" aria-controls="site-navigation" aria-expanded="${state.nav}"`)}<div class="breadcrumbs"><span>Workspace</span><b>/</b>${esc(title)}</div><div class="top-right">${btn(icon('search')+'<span>Search</span><kbd>/</kbd>','search','header-search','aria-label="Search HOODSET"')}<a class="btn create-set" href="#community" aria-label="Create a basket">${icon('community')}<span>CREATE BASKET</span></a>${btn(icon('portfolio')+`<span>${esc(ctx.connection())}</span>`,'connect','wallet-connect')}</div></header><main id="workspace-content" tabindex="-1"><div class="terminal-status ${state.error?'has-error':''}"><div><span class="network-label">RH MAINNET</span><span class="status-divider"></span><span data-price-status>${state.loading?'Reading official sources…':`${fresh}/${state.assets.length} fresh marks`}</span><span class="status-provider">OpenOcean routes</span></div>${btn(state.loading?'Updating…':'Refresh sources','refresh','text-btn','',state.loading)}</div>${state.error?`<div class="notice warn flex-between"><span>${esc(state.error)}</span>${btn('Retry','refresh','text-btn')}</div>`:''}${state.account&&state.chain!==4663?`<div class="notice warn flex-between"><span>Your wallet is on chain ${state.chain}. Switch to RH mainnet before trading.</span>${btn('SWITCH TO RH','switch','primary')}</div>`:''}${ctx.journeyPanel()}${body}<div class="history-attribution">Historical data: <a href="https://www.dolthub.com/repositories/post-no-preference/stocks" target="_blank" rel="noreferrer">post-no-preference/stocks</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA 4.0</a>. Selected and split-adjusted by HOODSET. <a href="#data">Source & changes</a>.</div><footer><a href="#discover"><strong>HOODSET<span>.</span></strong></a><span>Many assets. One conviction.</span><div><a href="#methodology">Methodology</a><a href="#data">Data & network</a><a href="https://github.com/hoodset/hoodset-app" target="_blank" rel="noreferrer">GitHub</a><a href="https://x.com/hoodsetq" target="_blank" rel="noreferrer">X</a></div></footer></main></div>`;
  }

  function chart(key) {
    const span = {'1H':3600000,'1D':86400000,'1W':604800000,'1M':2592000000}[state.period];
    const values = (ctx.observations()[key]||[]).filter(x => x.at >= Date.now()-span);
    const grid = [15,70,125,180].map(y=>`<line x1="0" x2="800" y1="${y}" y2="${y}" stroke="#cdd0c4" stroke-dasharray="2 6"/>`).join('');
    if (values.length < 2) return `<div class="observed-chart collecting"><svg viewBox="0 0 800 220" role="img" aria-label="${values.length?'One actual observation; history is collecting':'Waiting for a complete fresh valuation'}">${grid}${values.length?'<circle cx="18" cy="125" r="5" fill="#9569df"/>':''}</svg><div class="chart-collecting"><strong>${values.length?'FIRST MARK RECORDED.':'WAITING FOR FRESH MARKS.'}</strong><span>${values.length?'Observations accumulate in this browser.':'Every component needs a valid price.'}</span><small>Actual observations only. No backfilled returns.</small></div></div>`;
    const vals=values.map(v=>Number(BigInt(v.value))/1e18), min=Math.min(...vals), max=Math.max(...vals), pad=Math.max((max-min)*.18,max*.001),lo=min-pad,hi=max+pad;
    const duration=Math.max(1,values.at(-1).at-values[0].at);
    const points=vals.map((v,i)=>`${12+(values[i].at-values[0].at)/duration*776},${12+(1-(v-lo)/(hi-lo))*175}`).join(' ');
    const [x,y]=points.split(' ').at(-1).split(',');
    return `<div class="observed-chart"><svg viewBox="0 0 800 220" role="img" aria-label="Actual observed reference value from ${usd(BigInt(values[0].value))} to ${usd(BigInt(values.at(-1).value))}">${grid}<polygon points="12,190 ${points} 788,190" fill="#9569df" opacity=".06"/><polyline fill="none" stroke="#9569df" stroke-width="2.4" points="${points}"/><circle cx="${x}" cy="${y}" r="4" fill="#9569df"/><text x="12" y="215" font-size="12" fill="#70756a">${time(values[0].at)}</text><text x="735" y="215" font-size="12" fill="#70756a">${time(values.at(-1).at)}</text></svg></div>`;
  }

  const annualDate=at=>new Date(at).toLocaleDateString([], {month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
  function heroAnnual(t){
    const result=annual(t),waiting=state.historyLoading||!state.marketHistory;
    return `<div class="hero-annual"><div class="hero-annual-identity">${basketMark(t)}<span><b>${esc(t.name)}</b><small>1Y PRICE RETURN</small></span></div><strong class="${result.ready?(result.returnBps<0?'negative':'positive'):'unavailable'}">${returnLabel(result)}</strong><div class="hero-annual-meta"><span>${result.ready?'Historical mix / '+annualDate(result.end):waiting?'Loading annual history…':'Full annual history unavailable'}</span>${btn('VIEW 1Y','radar-open-performance','text-btn',`data-id="${t.id}"`)}</div></div>`;
  }
  function annualChart(result){
    if(!result.ready)return `<div class="observed-chart collecting"><div class="chart-collecting"><strong>${state.historyLoading||!state.marketHistory?'LOADING 1Y HISTORY.':'1Y HISTORY UNAVAILABLE.'}</strong><span>${esc(result.reason)}</span><small>Every component needs a complete common period.</small></div></div>`;
    const values=result.points.map(x=>Number(BigInt(x.value))/1e18),lo=Math.min(...values),hi=Math.max(...values),pad=Math.max((hi-lo)*.12,hi*.001),duration=result.end-result.start;
    const points=values.map((value,i)=>`${12+(result.points[i].at-result.start)/duration*776},${12+(hi+pad-value)/(hi-lo+pad*2)*175}`).join(' ');
    return `<div class="observed-chart annual-feature-chart"><svg viewBox="0 0 800 205" role="img" aria-label="1Y historical price calculation for the selected basket composition">${[20,75,130,185].map(y=>`<line x1="0" x2="800" y1="${y}" y2="${y}" stroke="#cdd0c4" stroke-dasharray="2 6"/>`).join('')}<polyline fill="none" stroke="#9569df" stroke-width="2.4" points="${points}"/></svg><div class="annual-chart-dates"><span>${annualDate(result.start)}</span><span>${annualDate(result.end)}</span></div></div>`;
  }
  function featured(t,annualView=false) {
    const r=reference(t), history=r?ctx.observations()['theme:'+r.key]||[]:[], first=history[0];
    const change=r?.value!=null&&first&&BigInt(first.value)>0n?Number((r.value-BigInt(first.value))*10000n/BigInt(first.value))/100:null;
    const year=annualView?annual(t):null;
    return `<section class="reference-feature ${annualView?'reference-feature--annual':''}"><div class="reference-main"><div class="feature-title"><div class="set-heading">${basketMark(t)}<div><small>REFERENCE ALLOCATION / ${t.symbol}</small><h2>${esc(t.name)}</h2></div></div>${btn(icon(saved.watch.includes(t.id)?'star-filled':'watchlist'),'watch','icon-btn',`data-id="${t.id}" aria-label="Toggle featured basket watchlist" aria-pressed="${saved.watch.includes(t.id)}"`)}</div>${annualView?`<div class="reference-value reference-annual-value"><div><strong class="${year.ready?(year.returnBps<0?'negative':'positive'):'unavailable'}">${returnLabel(year)}</strong><span>1Y price return${year.ready?' / $100 at start: '+usd(year.endValue):''}</span></div>${badge('1Y / DAILY CLOSES','lime')}</div>${annualChart(year)}<div class="chart-source"><span>HISTORICAL MIX / SPLIT-ADJUSTED STOCK CLOSES</span><a href="#data">Price methodology</a></div><p class="annual-feature-note">Current composition applied retrospectively. Initial weights, then fixed quantities. Excludes dividends, fees and token multiplier effects.</p>`:`<div class="reference-value"><div><strong>${usd(r?.value)}</strong><span>${history.length>1&&change!==null?`<b class="${change<0?'negative':'positive'}">${change>0?'+':''}${change.toFixed(2)}%</b> since first observation`:'Live reference value'}</span></div>${ctx.periods()}</div>${chart('theme:'+(r?.key||compositionKey(t)))}<div class="chart-source"><span>FIXED REFERENCE QUANTITIES${r?` / ${new Date(r.base.at).toLocaleDateString([], {month:'short',day:'numeric'})}`:''}</span><a href="#data">Price methodology</a></div>`}</div><div class="reference-side"><small>CURRENT REFERENCE WEIGHTS</small>${t.assets.map((s,i)=>`<div class="reference-component">${tokenMark(s)}<div><b>${s}</b><small>${esc(tokenName(s))}</small></div><strong>${r?.currentWeightsBps?(r.currentWeightsBps[i]/100).toFixed(2).replace(/\.00$/,''):'—'}<em>%</em></strong></div>`).join('')}<small class="initial-allocation-label">INITIAL ALLOCATION</small>${allocation(t.assets,t.weights)}<a class="btn primary wide" href="#theme/${t.id}">INSPECT ALLOCATION</a><small class="template-note">${t.custom?'Your custom mix':'Reference template'}. No issued basket share.</small></div></section>`;
  }

  function themeCard(t) {
    const fresh=t.assets.filter(s=>p(s)?.ok).length;
    return `<article class="set-card"><div class="set-card-top">${basketMark(t)}${btn(icon(saved.watch.includes(t.id)?'star-filled':'watchlist'),'watch','star',`data-id="${t.id}" aria-label="Toggle ${esc(t.name)} watchlist" aria-pressed="${saved.watch.includes(t.id)}"`)}</div><small>${esc(t.sector)} / ${t.symbol}</small><h3><a href="#theme/${t.id}">${esc(t.name)}</a></h3><p>${esc(t.thesis)}</p>${allocation(t.assets,t.weights)}<div class="set-card-return"><small>1Y PRICE RETURN / HISTORICAL MIX</small><strong class="${annual(t).returnBps<0?'negative':'positive'}">${returnLabel(annual(t))}</strong></div><div class="set-card-foot"><span>${fresh}/${t.assets.length} fresh marks</span><a href="#theme/${t.id}">Inspect set</a></div></article>`;
  }

  const annualCache=new Map();let annualData,annualMinute;
  function annual(t){const minute=Math.floor(Date.now()/60000);if(annualData!==state.marketHistory||annualMinute!==minute){annualData=state.marketHistory;annualMinute=minute;annualCache.clear();}const key=JSON.stringify([t.assets,t.weights]);if(!annualCache.has(key))annualCache.set(key,historicalBasket(t,state.marketHistory,'1Y'));return annualCache.get(key);}
  const returnLabel=r=>r.ready?(r.returnBps>0?'+':'')+(r.returnBps/100).toFixed(2)+'%':'—';
  function catalogue(list=themes, useFilter=true) {
    const rows=list.filter(t=>(!useFilter||state.filter==='All baskets'||t.sector===state.filter)&&`${t.name} ${t.assets.join(' ')}`.toLowerCase().includes(state.search.toLowerCase()));
    rows.sort((a,b)=>state.sort.startsWith('return-')?compareHistorical(annual(a),annual(b),state.sort==='return-asc'?'asc':'desc')||a.name.localeCompare(b.name):state.sort==='assets'?b.assets.length-a.assets.length:state.sort==='coverage'?(b.assets.filter(s=>p(s)?.ok).length/b.assets.length)-(a.assets.filter(s=>p(s)?.ok).length/a.assets.length):a.name.localeCompare(b.name));
    if (!rows.length) return empty('watchlist','NO MATCHING SETS.','Try another ticker or clear your filters.',btn('CLEAR FILTERS','clear-catalogue','primary'));
    if (state.catalogueView==='grid') return `<div class="set-card-grid">${rows.map(themeCard).join('')}</div>`;
    return `<div class="table-scroll catalogue-table"><table><thead><tr><th aria-label="Watchlist"></th><th>SET / THESIS</th><th>INITIAL COMPOSITION</th><th>1Y PRICE RETURN</th><th>PRICE COVERAGE</th><th></th></tr></thead><tbody>${rows.map(t=>{const fresh=t.assets.filter(s=>p(s)?.ok).length;return `<tr><td>${btn(icon(saved.watch.includes(t.id)?'star-filled':'watchlist'),'watch','star',`data-id="${t.id}" aria-label="Toggle ${esc(t.name)} watchlist" aria-pressed="${saved.watch.includes(t.id)}"`)}</td><td><a class="table-set" href="#theme/${t.id}">${basketMark(t)}<span><b>${esc(t.name)}</b><small>${t.symbol} / ${esc(t.sector)}</small></span></a></td><td>${chips(t.assets)}<div class="row-allocation">${t.weights.map((w,i)=>`<span style="flex:${w};background:${colors[i%colors.length]}"></span>`).join('')}</div></td><td><b class="${annual(t).returnBps<0?'negative':'positive'}" title="${esc(annual(t).ready?'Historical underlying price calculation; excludes dividends and token multiplier effects.':annual(t).reason)}">${returnLabel(annual(t))}</b><small>Historical mix</small></td><td><b>${fresh}/${t.assets.length}</b><small>${fresh===t.assets.length?'Complete reference':'Price unavailable'}</small></td><td><a class="btn inspect-btn" href="#theme/${t.id}">INSPECT</a></td></tr>`;}).join('')}</tbody></table></div>`;
  }

  function catalogueControls() {
    return `<div class="catalogue-toolbar"><label class="catalogue-search">${icon('search')}<input class="live-search" aria-label="Search themes" placeholder="Search sets or tickers" value="${esc(state.search)}"></label><div class="catalogue-tools"><select id="catalogue-sort" aria-label="Sort baskets"><option value="return-desc" ${state.sort==='return-desc'?'selected':''}>1Y return: highest first</option><option value="return-asc" ${state.sort==='return-asc'?'selected':''}>1Y return: lowest first</option><option value="name" ${state.sort==='name'?'selected':''}>Name A–Z</option><option value="assets" ${state.sort==='assets'?'selected':''}>Most assets</option><option value="coverage" ${state.sort==='coverage'?'selected':''}>Price coverage</option></select><div class="view-switch" role="group" aria-label="Basket display">${btn(icon('menu'),'catalogue-view',state.catalogueView==='list'?'active':'','data-view="list" aria-label="List view" aria-pressed="'+(state.catalogueView==='list')+'"')}${btn(icon('tokens'),'catalogue-view',state.catalogueView==='grid'?'active':'','data-view="grid" aria-label="Grid view" aria-pressed="'+(state.catalogueView==='grid')+'"')}</div></div></div>`;
  }

  function discover() {
    const t=themes.find(x=>x.id===state.selected)||themes[0];
    return `<section class="hero terminal-hero"><div class="hero-copy"><div class="eyebrow">THE ROBINHOOD CHAIN BASKET TERMINAL</div><h1>YOUR THESIS.<br>ONE BASKET.</h1><p>Turn a market view into a set of Stock Tokens.<br>Know exactly what backs every share.</p>${heroAnnual(t)}<div class="button-row"><a class="btn primary" href="#community">BUILD A BASKET</a><a class="btn" href="#radar">COMPARE SETS</a></div><div class="hero-principles"><span>Fixed composition</span><span>Wallet signed</span><span>Transparent backing</span></div></div><div class="assembly-art"><div class="art-meta"><span>COMPOSITION / RH</span><span>01 SHARE · MULTIPLE ASSETS</span></div><img src="/assets/basket-assembly.jpg" alt="Three distinct asset blocks held together inside one open basket frame" width="1024" height="1024"><div class="assembly-labels"><span>NVDA</span><span>AMD</span><span>AVGO</span></div><small>Illustrated structure / not a deployed vault</small></div></section><div class="terminal-metrics">${stat('VERIFIED STOCK TOKENS',state.assets.length||'—','Official RH registry')}${stat('FRESH PRICE COVERAGE',`${Object.values(state.prices).filter(x=>x.ok).length}<em>/${state.assets.length}</em>`,'Token-adjusted marks')}${stat('ALLOCATION THEMES',themes.length,'Build from a starting set')}${stat('YOUR ONCHAIN SETS',Object.keys(state.vaults).length,'This browser’s address book')}</div>${radarUI.render()}${section('A VIEW WORTH OWNING.','Inspect a reference allocation. Create your own share when you are ready.')}<div class="theme-tabs" role="group" aria-label="Featured allocation">${themes.map(x=>btn(x.name,'select-theme',x.id===t.id?'active':'',`data-id="${x.id}" aria-pressed="${x.id===t.id}"`)).join('')}</div>${featured(t,true)}${section('FIND YOUR CONVICTION.','Allocation templates. No vault or tradable share is implied.')}<div class="catalogue-section">${catalogueControls()}<div class="filters">${['All baskets',...new Set(themes.map(t=>t.sector))].map(x=>btn(x,'filter',state.filter===x?'active':'',`data-filter="${x}" aria-pressed="${state.filter===x}"`)).join('')}</div>${catalogue()}</div><div class="market-callout"><div>${icon('onchain')}<h3>COMPONENTS FIRST.<br>YOUR SHARE NEXT.</h3></div><p>Acquire Stock Tokens through OpenOcean, then deposit the exact composition to mint your basket shares.</p><a class="btn" href="#tokens">OPEN TOKEN MARKET</a></div>`;
  }

  function watchlist() {
    const list=themes.filter(t=>saved.watch.includes(t.id));
    return `${ctx.heading('YOUR CONVICTION.<br>ON WATCH.','Your saved allocations, ready for a closer look.','WATCHLIST / '+list.length+' SAVED SETS')}${list.length?`<div class="terminal-metrics compact">${stat('SAVED ALLOCATIONS',list.length)}${stat('DISTINCT COMPONENTS',new Set(list.flatMap(t=>t.assets)).size)}${stat('ISSUED SHARES','—','These are templates')}</div>${catalogueControls()}${catalogue(list,false)}`:empty('watchlist','KEEP YOUR NEXT IDEA CLOSE.','Save a set from Discover. Its current composition and price coverage will appear here.','<a class="btn primary" href="#discover">EXPLORE ALLOCATIONS</a>')}`;
  }

  function sectors() {
    const unique=[...new Set(themes.flatMap(t=>t.assets))], fresh=unique.filter(s=>p(s)?.ok).length;
    return `${ctx.heading('THE SECTOR<br>LANDSCAPE.','Compare thematic coverage across the verified Stock Token universe.','SECTORS / REAL SOURCE COVERAGE')}<div class="terminal-metrics compact">${stat('ALLOCATION THEMES',themes.length)}${stat('COMPONENTS COVERED',unique.length)}${stat('FRESH MARKS',`${fresh}<em>/${unique.length}</em>`)}</div>${btn('COMPARE 1Y PRICE RETURNS','radar-open-performance','primary')}${section('COVERAGE BY THEME.','Coverage measures available pricing. It is not an investment return ranking.')}<div class="sector-ledger">${themes.map(t=>{const n=t.assets.filter(s=>p(s)?.ok).length;return `<a href="#theme/${t.id}" class="sector-row"><div class="table-set">${basketMark(t)}<span><b>${esc(t.name)}</b><small>${esc(t.sector)}</small></span></div><div>${chips(t.assets)}<div class="coverage-track"><span style="width:${n/t.assets.length*100}%"></span></div></div><div><strong>${n}/${t.assets.length}</strong><small>fresh marks</small></div><span class="sector-open">VIEW SET</span></a>`;}).join('')}</div><div class="editorial-note">${icon('data')}<p>Compare the same completed market sessions in Basket Radar. Historical price returns use the selected composition and initial weights; they are separate from live price coverage and an issued vault’s track record.</p></div>`;
  }

  function themeEvidence(t) {
    const members=t.custom?[]:t.members||[];
    return `<section class="panel theme-evidence"><div class="panel-heading"><h2>WHY THESE ASSETS?</h2>${badge(t.custom?'YOUR SELECTION':'EDITORIAL TEMPLATE')}</div>${t.custom?`<p>Your saved mix is preserved. It is independent of the current ${esc(t.templateName||'reference')} template and may fall outside its inclusion rules.</p>`:`<p><b>Inclusion rule.</b> ${esc(t.rule)}</p><div class="theme-member-list">${members.map(m=>`<article><strong>${esc(m.symbol)}</strong><div><p>${esc(m.role)}</p><a href="${esc(m.source)}" target="_blank" rel="noreferrer">Company / issuer source</a></div></article>`).join('')}</div><p class="footnote">${esc(t.limit)}</p><p class="footnote">${esc(TEMPLATE_WEIGHT_METHOD)} Sources reviewed November 27, 2026.</p>`}<a href="#methodology">How templates are selected</a></section>`;
  }

  function themePage(id) {
    const t=themes.find(x=>x.id===id);if(!t)return ctx.missing();const r=reference(t);
    return `<div class="detail-identity">${basketMark(t)}${badge(t.custom?'YOUR CUSTOM MIX':'ALLOCATION TEMPLATE')}<span>${t.assets.length} Stock Tokens</span></div>${ctx.heading(esc(t.name).toUpperCase()+'.',esc(t.thesis),'YOUR STARTING COMPOSITION')}${btn('VIEW 1Y PRICE HISTORY','radar-open-performance','',`data-id="${t.id}"`)}${featured(t)}${themeEvidence(t)}<div class="detail-grid"><section class="panel"><div class="panel-heading"><h2>THE UNDERLYING SET.</h2>${badge('REFERENCE')}</div>${r?ctx.composition(t.assets,r.base.amounts,t.weights.map(w=>Math.round(w*100))):'<div class="notice">Complete fresh marks are required before quantities can be calculated.</div>'}<p class="footnote">Fixed reference quantities were recorded by this browser. A new vault uses fresh quantities at your chosen initial weights. Execution costs differ.</p></section><aside class="panel action-panel"><small>YOUR THESIS, YOUR COMPOSITION</small><h2>MAKE IT<br>YOUR SET.</h2><p>Name your share, adjust the weights and review your own vault deployment.</p>${btn('CUSTOMIZE THIS SET','template','primary wide',`data-id="${t.id}"`)}<a class="btn wide" href="#tokens">INSPECT COMPONENT TOKENS</a><p class="footnote">This template has no deployed vault, issued supply or backing. Deploying and funding a basket are separate actions.</p></aside></div>`;
  }

  function draftPreview() {
    const draft=ctx.draft();let summary;try{summary=mixSummary({assets:draft.assets.map(a=>a.symbol),weights:draft.assets.map(a=>a.weight)});}catch{}let data,error='';try{data=initialAmounts(draft.assets,state.prices);}catch(e){error=e.message;}
    return `<section class="panel draft-preview"><div class="preview-heading"><small>ONE SHARE / REFERENCE PREVIEW</small>${badge(esc(draft.symbol||'YOUR SET'))}</div><h2>${esc(draft.name||'YOUR NEXT SET.')}</h2><p>${esc(draft.thesis||'A clear thesis. A composition you can inspect.')}</p>${allocation(draft.assets.map(a=>a.symbol),draft.assets.map(a=>a.weight))}<div class="builder-mix-summary"><span><b>${draft.assets.length}</b> components</span><span><b>${summary?summary.largestBps/100+'%':'—'}</b> largest weight</span></div>${draft.budgetUSDG?`<div class="radar-builder-budget"><span>Planned component budget</span><strong>${esc(draft.budgetUSDG)} USDG</strong><small>Reference estimate. Swap costs and gas are additional.</small></div>`:''}<div class="preview-summary"><span>Initial reference size</span><strong>${data?'≈ $100.00':'—'}</strong></div>${data?`<div class="preview-assets">${draft.assets.map((a,i)=>`<div>${tokenMark(a.symbol)}<span><b>${a.symbol}</b><small>${units(data.amounts[i],18,10)} tokens / share</small></span><strong>${a.weight}%</strong></div>`).join('')}</div>`:`<div class="notice warn">${esc(error)}</div>`}<div class="preview-rule">${icon('onchain')}<p>Quantities are fixed at creation. Current weights move with market prices.</p></div></section>`;
  }

  function builder() {
    const draft=ctx.draft();const total=draft.assets.reduce((s,a)=>s+Number(a.weight||0),0);
    return `${ctx.heading('BUILD YOUR<br>CONVICTION.','Choose the assets. Set the weights. Review what one share contains.','CREATE A BASKET / RH MAINNET')}${saved.radarPreviousDraft?`<div class="radar-builder-origin"><span>Loaded from Basket Radar. Your previous draft is kept.</span>${btn('Restore previous draft','radar-restore-draft','text-btn')}</div>`:''}<div class="builder-stage-rail"><span class="active">Composition</span><span>Deploy vault / gas only</span><span>Buy tokens & mint</span></div><div class="community-grid builder-workspace"><section class="panel builder"><div class="panel-heading"><h2>THE SET.</h2>${badge('2–12 ASSETS')}</div><div class="builder-templates"><span>Start with a theme</span><div>${themes.map(t=>btn(t.name,'template','',`data-id="${t.id}"`)).join('')}</div></div><form id="live-builder"><div class="identity-fields"><label>Basket name<input aria-label="Basket name" name="name" maxlength="48" required value="${esc(draft.name)}" placeholder="Your conviction"></label><label>Share symbol<input aria-label="Share symbol" name="symbol" maxlength="8" required value="${esc(draft.symbol)}" placeholder="e.g. CHIP"></label></div><label>Your thesis<textarea aria-label="Basket thesis" name="thesis" maxlength="280" required placeholder="What brings these assets together?">${esc(draft.thesis)}</textarea></label><div class="flex-between token-title"><h3>ASSETS & WEIGHTS</h3>${btn('Equal weights','equal','text-btn')}</div><div class="builder-assets">${ctx.builderRows()}</div><div class="builder-total flex-between">${btn(icon('community')+' ADD ASSET','add','','',draft.assets.length>=12)}<span class="weight-total ${total===100?'balanced':''}">${total.toFixed(2)} / 100%</span></div><label>Maximum shares<input name="maxSupply" aria-label="Maximum shares" type="number" min="1" max="1000000" step="1" value="${esc(draft.maxSupply)}" required></label><div class="deployment-note"><b>Before you deploy</b><p>A new vault is a new smart contract. Deployment costs ETH gas and buys no Stock Tokens. Independent audit has not been completed.</p></div><div id="builder-error" class="form-error" role="alert"></div><button class="btn primary wide" type="submit">${state.account?'REVIEW DEPLOYMENT':'CONNECT WALLET TO REVIEW'}</button></form></section><aside class="builder-preview-column"><div id="live-preview">${draftPreview()}</div><details class="source-disclosure"><summary>Inspect the contract</summary><p>Fixed composition. No administrator withdrawal or upgrade functions.</p><a href="/chain/HoodsetVault.sol" target="_blank" rel="noreferrer">Solidity source</a><a href="/chain/standard-input.json" target="_blank" rel="noreferrer">Reproducible compiler input</a><small>${esc(state.artifact?.compiler||'Compiler loading')} / ${state.artifact?.runtimeBytes||'—'} runtime bytes. Tests do not replace independent review.</small></details></aside></div>`;
  }

  function importPanel() {
    return `<section class="panel vault-import"><div class="import-heading">${icon('onchain')}<div><small>OPEN A SHARED BASKET</small><h2>HAVE A VAULT ADDRESS?</h2></div></div><p>Inspect its composition, supply and active backing on Robinhood Chain. The runtime and assets are verified before any approval is offered.</p><form id="import-form" class="import-form"><input name="address" aria-label="Vault address" placeholder="Paste a HOODSET vault address / 0x…" required spellcheck="false" autocomplete="off"><button class="btn primary" type="submit">OPEN VAULT</button></form><div id="import-error" class="form-error" role="alert"></div></section>`;
  }

  function knownSets() {
    const vaults=Object.values(state.vaults);
    if(!vaults.length)return empty('onchain','YOUR FIRST SET<br>STARTS HERE.','Create a vault for your thesis, or open a shared HOODSET address to inspect its real backing.','<a class="btn primary" href="#community">CREATE A BASKET</a>');
    return vaults.map(v=>`<a class="community-card known-set" href="#basket/${v.address}"><div class="set-card-top"><span class="empty-emblem">${icon('onchain')}</span>${badge('RUNTIME MATCH')}</div><small>${esc(v.symbol)} / ${v.symbols.length} ASSETS</small><h2>${esc(v.name)}</h2><p>${esc(v.thesis)}</p>${chips(v.symbols)}<div class="meta-pair"><span>Outstanding shares</span><strong>${units(v.supply)}</strong></div><div class="meta-pair"><span>Active backing estimate</span><strong>${usd(completeValue(v.symbols,v.available,state.prices))}</strong></div><div class="set-card-foot"><span>${short(v.address)}</span><b>INSPECT VAULT</b></div></a>`).join('');
  }

  function onchain() {
    return `${ctx.heading('YOUR THESIS.<br>ONCHAIN.','Inspect the vault. Know its backing. Mint and redeem through your wallet.','REDEEMABLE BASKET SHARES')}<div class="terminal-metrics compact">${stat('KNOWN VAULTS',Object.keys(state.vaults).length)}${stat('COMPOSITION','Fixed','No automatic rebalancing')}${stat('CUSTODY','Your wallet','Every write needs a signature')}</div>${importPanel()}${Object.entries(state.vaultErrors).map(([a,e])=>`<div class="notice warn">${short(a)}: ${esc(e)}</div>`).join('')}${section('YOUR ONCHAIN SETS.','Local address book. Supply and backing are read from the chain.')}<div class="live-set-grid ${Object.keys(state.vaults).length?'':'is-empty'}">${knownSets()}</div>`;
  }

  function activity() {
    const list=saved.activity.filter(x=>state.account&&x.account===state.account);
    return list.map(x=>`<div class="activity-row"><div><span class="activity-kind">${icon('onchain')}</span><span><b>${esc(x.label)}</b><small>${new Date(x.at).toLocaleString()}</small>${x.recoveryError?`<small class="form-error">Receipt check: ${esc(x.recoveryError)}</small>`:''}</span></div><a class="address" target="_blank" rel="noreferrer" href="https://robinhoodchain.blockscout.com/tx/${x.hash}">${short(x.hash)} / ${esc(x.status)}</a></div>`).join('')||empty('data','A CLEAR TRANSACTION TRAIL.','Transactions initiated by this browser appear here after submission, with their actual receipt status and explorer link.');
  }

  function portfolio() {
    const positions=Object.values(state.vaults).filter(v=>v.owned>0n),symbols=Object.keys(state.balances).filter(a=>state.balances[a]>0n);
    const walletValue=state.account?completeValue(symbols,symbols.map(a=>state.balances[a]),state.prices):null;
    const parts=positions.map(v=>completeValue(v.symbols,v.available.map(x=>x*v.owned/v.supply),state.prices));
    const reserves=Object.values(state.vaults).flatMap(v=>(v.exits||[]).filter(e=>!e.claimed).map(e=>completeValue(v.symbols,e.amounts,state.prices)));
    const complete=state.account&&state.balanceComplete&&walletValue!==null&&!parts.includes(null)&&!reserves.includes(null)&&!Object.keys(state.vaultErrors).length;
    const total=complete?walletValue+(state.usdg||0n)*10n**12n+parts.reduce((a,b)=>a+b,0n)+reserves.reduce((a,b)=>a+b,0n):null;
    const tab=state.portfolioTab||'positions';let content='';
    if(tab==='activity')content=activity();
    else if(!state.account)content=empty('portfolio','YOUR WALLET.<br>YOUR ASSETS.','Connect a browser wallet to inspect Stock Token balances, basket shares and reserved exits.',btn('CONNECT WALLET','connect','primary'));
    else if(tab==='positions')content=positions.length?`<div class="table-scroll"><table><thead><tr><th>BASKET</th><th>SHARES</th><th>REFERENCE VALUE</th><th></th></tr></thead><tbody>${positions.map((v,i)=>`<tr><td><a class="table-name" href="#basket/${v.address}">${esc(v.name)}</a><small>${esc(v.symbol)}</small></td><td>${units(v.owned,18,12)}</td><td>${usd(parts[i])}</td><td><div class="position-actions"><a class="btn" href="#basket/${v.address}">MANAGE</a><a class="btn" href="#exit/${v.address}">SELL FOR USDG</a></div></td></tr>`).join('')}</tbody></table></div>${positions.map(v=>`<details class="position-contents panel"><summary>${esc(v.symbol)} / See Stock Tokens inside your shares</summary>${positionPanel(v,state.prices,{esc})}</details>`).join('')}`:empty('onchain','NO BASKET SHARES YET.','Open a vault you already hold, or create a basket with your chosen composition.','<a class="btn primary" href="#onchain">OPEN A VAULT</a>');
    else if(tab==='tokens')content=symbols.length?`<p class="notice">These are Stock Tokens held directly in your wallet, including purchase leftovers. Tokens backing your basket shares are shown under Basket shares.</p><div class="table-scroll"><table><thead><tr><th>STOCK TOKEN</th><th>BALANCE</th><th>REFERENCE VALUE</th><th></th></tr></thead><tbody>${symbols.map(s=>`<tr><td><div class="token-identity">${tokenMark(s)}<span><b>${s}</b><small>${esc(tokenName(s))}</small></span></div></td><td>${units(state.balances[s],18,8)}</td><td>${usd(p(s)?.ok?state.balances[s]*p(s).mid18/SCALE:null)}</td><td>${btn('SELL','sell-token','',`data-symbol="${s}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('tokens','NO SUPPORTED STOCK TOKENS.','Your wallet has no balances in the currently verified Stock Token universe.','<a class="btn primary" href="#tokens">EXPLORE TOKEN MARKET</a>');
    else content=reserves.length?Object.values(state.vaults).map(ctx.exitList).join(''):empty('onchain','NO RESERVED EXITS.','Reserved redemptions are segregated from active backing and can be claimed once by their owner.');
    return `${ctx.heading('MY PORTFOLIO.','Your Stock Tokens and basket shares, with backing you can inspect.','YOUR WALLET / RH MAINNET')}<div class="portfolio-dashboard"><div class="portfolio-total"><small>TRACKED STOCK TOKEN & USDG VALUE</small><strong>${usd(total)}</strong><span>${state.account?'Supported balances and known vault positions':'Connect your wallet to read balances'}</span><p>Excludes ETH and unsupported assets. Historical cost basis and P&L are not indexed.</p></div><div class="portfolio-cash"><div class="meta-pair"><span>USDG balance</span><strong>${units(state.usdg,6,6)}</strong></div><div class="meta-pair"><span>ETH for gas</span><strong>${units(state.eth,18,8)}</strong></div><div class="meta-pair"><span>Basket positions</span><strong>${state.account?positions.length:'—'}</strong></div><a class="btn wide" href="#tokens">OPEN TOKEN MARKET</a></div></div><div class="portfolio-tabs" role="group" aria-label="Portfolio sections">${[['positions','Basket shares'],['tokens','Loose Stock Tokens'],['exits','Reserved exits'],['activity','Activity']].map(([id,label])=>btn(label,'portfolio-tab',tab===id?'active':'',`data-tab="${id}" aria-pressed="${tab===id}"`)).join('')}</div><section class="portfolio-content">${content}</section><div class="editorial-note">${icon('data')}<p>Vault positions use this browser’s address book. <a href="#onchain">Import other HOODSET addresses</a> to include them. External transfers and historical cost basis are not inferred.</p></div>`;
  }

  function swapForm() {
    const buy=state.swap.side==='buy',s=state.swap.symbol;
    return `<section class="panel swap-panel" id="token-order"><div class="panel-heading"><h2>TRADE TOKENS.</h2>${badge('OPENOCEAN')}</div><div class="swap-asset">${tokenMark(s)}<div><strong>${esc(s)}</strong><small>${esc(tokenName(s))}</small></div><span>RH / USDG</span></div><div class="trade-tabs" role="group" aria-label="Trade direction">${btn('BUY','swap-side',buy?'active':'','data-side="buy" aria-pressed="'+buy+'"')}${btn('SELL','swap-side',!buy?'active':'','data-side="sell" aria-pressed="'+(!buy)+'"')}</div><label>Stock Token<select id="swap-symbol" aria-label="Swap token">${state.assets.map(a=>`<option ${a.tokenSymbol===s?'selected':''}>${a.tokenSymbol}</option>`).join('')}</select></label><label class="spend-field"><span>${buy?'USDG TO SPEND':'TOKENS TO SELL'}</span><div><input id="swap-amount" aria-label="Swap amount" type="number" min="0" step="any" value="${esc(state.swap.amount)}"><b>${buy?'USDG':esc(s)}</b></div></label><div class="swap-balance"><span>Wallet balance</span><b>${state.account?units(buy?state.usdg:state.balances[s],buy?6:18,8):'Not connected'}</b></div>${state.swap.targetAmount?`<p class="footnote">Component target: ${units(BigInt(state.swap.targetAmount),18,10)} ${s}. This budget is an estimate. Check the actual minimum output before buying.</p>`:''}<label class="slippage-field">Slippage allowance<select id="swap-slippage" aria-label="Swap slippage">${[50,100,200,300].map(v=>`<option value="${v}" ${v===state.swap.slippage?'selected':''}>${v/100}%</option>`).join('')}</select></label><div id="swap-error" class="form-error" role="alert"></div>${!state.account?btn('CONNECT WALLET','connect','primary wide'):state.chain!==4663?btn('SWITCH TO RH MAINNET','switch','primary wide'):btn(state.quoteBusy?'GETTING LIVE QUOTE…':'GET LIVE QUOTE','get-quote','primary wide','',state.quoteBusy||!state.status?.swapConfigured)}<p class="swap-signature">${icon('portfolio')} You review and sign every transaction.</p>${state.quote?ctx.quotePanel():''}${ctx.lastSwapPanel()}<details class="trade-disclosure"><summary>Execution, fees & eligibility</summary><p>Exact input. The quote states the minimum output after provider deductions and slippage. Approval and swap each need a separate wallet confirmation.</p><p>OpenOcean public fees are 0.01–0.5% by pair category, plus ETH gas and pool costs. <a href="https://docs.openocean.finance/docs/swap-api/api-pricing-and-access" target="_blank" rel="noreferrer">Provider fees</a>.</p><p>Stock Token access depends on your jurisdiction. <a href="https://docs.robinhood.com/chain/stock-tokens/" target="_blank" rel="noreferrer">RH restrictions</a> apply even when a route is available.</p></details></section>`;
  }

  function tokens() {
    const rows=state.assets.filter(a=>`${a.tokenSymbol} ${a.tokenName}`.toLowerCase().includes((state.tokenSearch||'').toLowerCase())&&(state.tokenFilter!=='unavailable'||!p(a.tokenSymbol)?.ok)).sort((a,b)=>a.tokenSymbol.localeCompare(b.tokenSymbol));
    return `${ctx.heading('STOCK TOKENS.','Verified Stock Tokens. Real reference marks. Wallet-signed execution.','KNOW WHAT YOU OWN')}<div class="market-layout"><section class="panel token-universe"><div class="panel-heading"><h2>THE INSTRUMENTS.</h2>${badge(state.assets.length+' VERIFIED')}</div><div class="token-toolbar"><label class="catalogue-search">${icon('search')}<input class="token-search" aria-label="Search Stock Tokens" placeholder="Search ticker or company" value="${esc(state.tokenSearch||'')}"></label><select id="token-filter" aria-label="Filter price status"><option value="all">All prices</option><option value="unavailable" ${state.tokenFilter==='unavailable'?'selected':''}>Unavailable marks</option></select></div><div class="table-scroll token-market-table"><table><thead><tr><th>STOCK TOKEN</th><th>REFERENCE BID / ASK</th><th>SOURCE</th><th></th></tr></thead><tbody>${rows.map(a=>{const s=a.tokenSymbol,mark=p(s);return `<tr class="${s===state.swap.symbol?'selected-token':''}"><td><div class="token-identity">${tokenMark(s)}<span><b>${s}</b><small>${esc(tokenName(s))}</small><a class="address" href="https://robinhoodchain.blockscout.com/address/${ALLOWED[s]}" target="_blank" rel="noreferrer">${short(ALLOWED[s])}</a></span></div></td><td><div class="quote-prices"><b>${mark?.ok?usd(mark.bid18):'—'}</b><span>${mark?.ok?usd(mark.ask18):'—'}</span></div></td><td><span class="source-tag ${mark?.ok?'':'unavailable'}">${mark?.ok?'AVAILABLE':'UNAVAILABLE'}</span><small>${ctx.sourceAge(s)}</small></td><td>${btn('TRADE','trade-token','text-btn',`data-symbol="${s}" aria-label="Trade ${s}"`)}</td></tr>`;}).join('')}</tbody></table>${rows.length?'':empty('search','NO MATCHING TOKENS.','Try a different ticker or price status.',btn('CLEAR SEARCH','clear-tokens','primary'))}</div><p class="footnote">Reference bid/ask is not an executable quote. Underlying prices are adjusted once with the token multiplier. A missing, stale or paused mark stops valuation.</p></section><aside class="market-order-column">${swapForm()}</aside></div>`;
  }

  function methodology() {
    const rules=[['sectors','EXPLAINED TEMPLATES.','Editorial starting sets are limited to the supported RH universe. Each template states a business inclusion rule and links to company or issuer sources. They are not exhaustive sector indexes.'],['sectors','TRANSPARENT STARTING WEIGHTS.',TEMPLATE_WEIGHT_METHOD+' Initial equal weights do not stay equal as prices move. Saved custom mixes retain your own weights.'],['data','HINDSIGHT IS VISIBLE.','Today’s selected assets are shown over past prices. Membership was not fixed a year ago; the result is a retrospective illustration, not an out-of-sample strategy or a forecast. A higher trailing return is not a buy signal.'],['tokens','CANONICAL ASSETS.','Basket creation permits the verified RH Stock Token addresses in this contract release. Each component must have 18 decimals.'],['onchain','FIXED QUANTITIES.','Initial weights set token quantities when the vault is created. Prices change current weights; they never trigger automatic rebalancing.'],['portfolio','PRO-RATA TOKEN CLAIM.','A share claims a proportion of active underlying balances. Mints round deposits up and redemptions round down. Donations and residues belong to holders.'],['check','YOUR SIGNATURES.','Initial exact permissions are separate. Batch execution combines component swaps and mint, or redemption and component sales, into one transaction. Every send requires your wallet confirmation.'],['onchain','SEGREGATED EXITS.','Reserving an exit burns shares and records token quantities for that wallet. Reserved tokens leave active backing and can be claimed once by their owner.'],['data','TWO DISTINCT HISTORIES.','Live reference charts use browser observations. Basket Radar also models a chosen mix from real split-adjusted underlying daily closes: initial weights, fixed quantities, no cash dividends or token multiplier effects. Neither view invents an issued vault track record.']];
    return `${ctx.heading('KNOW YOUR<br>SHARE.','The thesis is yours. The mechanics should be clear.','THE HOODSET METHODOLOGY')}<section class="method-equation"><div><small>THE RELATIONSHIP</small><h2>MANY ASSETS.<br>ONE CLAIM.</h2></div><p>Token quantities per share <b>×</b> current token marks <b>=</b> reference share value</p></section>${section('FROM THESIS TO OWNERSHIP.','A sequence of explicit actions, each under your control.')}<div class="ownership-flow"><article><span>01 / ACQUIRE</span>${icon('tokens')}<h3>START WITH USDG.</h3><p>Choose your basket and budget. Review exact token permissions, then a fresh quote with minimum shares and gas.</p><a href="#tokens">Explore token market</a></article><article><span>02 / MINT</span>${icon('onchain')}<h3>RECEIVE BASKET SHARES.</h3><p>One batch transaction buys the components and deposits them into the vault. Basket shares arrive in your wallet; unused component tokens are returned separately.</p><a href="#community">Build a basket</a></article><article><span>03 / REDEEM</span>${icon('portfolio')}<h3>EXIT BACK TO USDG.</h3><p>After share permission, one batch transaction burns your shares, redeems the proportional Stock Tokens and sells them for USDG. Token-only withdrawal and reserved exits remain available.</p><a href="#onchain">Inspect onchain sets</a></article></div><div class="method-grid">${rules.map(([glyph,h,text])=>`<article><span class="rule-icon">${icon(glyph)}</span><div><h3>${h}</h3><p>${text}</p></div></article>`).join('')}</div><div class="editorial-note">${icon('data')}<p>Batch execution reverts together if a component fails; gas may still be charged. Individual steps are optional and can leave acquired components in your wallet until resumed. A runtime match is not an independent audit.</p></div>`;
  }

  function historySourcePanel(){
    const h=state.marketHistory,available=h?.configured&&h.displayAvailable!==false,count=Object.keys(h?.series||{}).length;
    const message=state.historyError||h?.error;
    return `<section class="panel history-source-panel"><div class="panel-heading"><h2>HISTORICAL PRICES.</h2>${badge(state.historyLoading?'LOADING':available?count+'/17 LOADED':'UNAVAILABLE',available?'lime':'')}</div><p>Community-maintained daily stock and ETF closes from post-no-preference/stocks on DoltHub. Raw prices are adjusted for published splits by HOODSET; cash dividends are excluded. Completed sessions only. The cache refreshes after six hours when the site is used.</p>${message?`<p class="${h?.displayAvailable===false?'footnote':'form-error'}">${esc(message)}</p>`:''}${h?.displayAvailable===false?'<p>Annual returns stay unranked while history is unavailable. Current RH reference marks and wallet-signed trading use separate sources.</p>':''}<div class="history-source-actions">${btn(state.historyLoading?'READING HISTORY…':'REFRESH HISTORY','radar-refresh-history','', '',state.historyLoading||h?.displayAvailable===false)}<a href="https://www.dolthub.com/repositories/post-no-preference/stocks" target="_blank" rel="noreferrer">Source database</a><a href="/data/stock-history-source.json" target="_blank" rel="noreferrer">Data & change notice</a><a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noreferrer">CC BY-SA 4.0</a></div>${h?.snapshot?`<p class="footnote">Latest source check: ${esc(new Date(h.snapshot.checkedAt).toLocaleString())}. Latest source revision: <code>${esc(h.snapshot.latestSourceRevision)}</code>. ${h.cacheStale?'Refresh is delayed; only complete dated periods remain ranked.':'A verified dated bootstrap is available while the shared cache warms.'}</p>`:''}${available?`<div class="history-health-grid">${Object.keys(ALLOWED).map(symbol=>`<div><b>${symbol}</b><span>${h.series[symbol]?h.series[symbol].points.length+' daily closes / through '+h.series[symbol].last:esc(h.errors?.[symbol]||'Waiting for history')}</span></div>`).join('')}</div>`:''}</section>`;
  }

  function data() {
    const fresh=Object.values(state.prices).filter(x=>x.ok).length;
    return `${ctx.heading('DATA, WITH<br>THE DETAILS.','Inspect the sources behind the numbers and the network behind your shares.','DATA & NETWORK')}<div class="terminal-metrics compact">${stat('NETWORK','4663','Robinhood Chain mainnet')}${stat('ASSET REGISTRY',state.assets.length||'—','Verified canonical contracts')}${stat('FRESH REFERENCE MARKS',`${fresh}<em>/${state.assets.length}</em>`,'120 second freshness limit')}</div>${ctx.connectionPanel()}${historySourcePanel()}<div class="data-grid"><section class="panel"><div class="panel-heading"><h2>CONNECTIONS.</h2>${badge(state.loading?'READING':'SOURCE CONFIGURATION')}</div>${[['Chain','Robinhood Chain / 4663'],['Gas currency','ETH'],['Read RPC',state.status?.rpcProvider||'Checking'],['Wallet',state.account?short(state.account):'Not connected'],['Quote provider','OpenOcean public API'],['Quote transport','Direct from your browser'],['Swap API key','Not required for public access'],['Historical source','DoltHub / CC BY-SA 4.0']].map(([k,v])=>`<div class="meta-pair"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}<p class="footnote">Public RPC reads are rate-limited. A dedicated server RPC can improve reliability. A configured source does not guarantee a route or liquidity.</p><a class="btn wide" href="/diagnostics.html" target="_blank" rel="noreferrer">RUN READ-ONLY ROUTE CHECK</a></section><section class="panel source-guide"><h2>WHAT THE NUMBERS MEAN.</h2><article><b>Reference prices</b><p>Official RH REST bid/ask, adjusted once by the current token uiMultiplier(). A paused oracle, halted market, missing mark or price older than 120 seconds is unavailable.</p></article><article><b>Executable prices</b><p>A fresh OpenOcean quote states your exact spend and minimum output. Pool costs, provider deductions and slippage differ from reference marks.</p></article><article><b>Historical price return</b><p>Basket Radar uses DoltHub community daily closes, adjusted for published splits by HOODSET. A $100 starting mix buys fixed split-adjusted units at the selected initial weights. Cash dividends, costs and RH multiplier effects are excluded. The same SPY session calendar sets each ranked basket’s start and end; missing components remain unranked.</p></article><article><b>Vault history & portfolio</b><p>Live vault charts still use actual browser observations. Underlying price history is not actual token execution history or your portfolio P&L. Full cost basis and a global vault directory require an indexer.</p></article></section></div>${section('PRICE SOURCE HEALTH.','Every supported component stays visible, including missing or stale marks.')}<div class="table-scroll health-table"><table><thead><tr><th>STOCK TOKEN</th><th>REFERENCE MARK</th><th>STATE</th><th>OBSERVATION</th></tr></thead><tbody>${state.assets.map(a=>{const s=a.tokenSymbol;return `<tr><td><strong>${s}</strong></td><td>${ctx.priceLabel(s)}</td><td><span class="source-tag ${p(s)?.ok?'':'unavailable'}">${p(s)?.ok?'FRESH':'UNAVAILABLE'}</span></td><td>${ctx.sourceAge(s)}</td></tr>`;}).join('')}</tbody></table></div><section class="panel contract-library"><div><small>INSPECT BEFORE YOU SIGN</small><h2>THE CONTRACT,<br>IN THE OPEN.</h2><p>Deployment costs ETH gas and creates an empty vault. Batch purchase then funds it with Stock Tokens and issues basket shares. The app checks the vault runtime and canonical assets before offering approvals. Independent audit has not been completed.</p></div><div class="source-links"><a href="https://github.com/hoodset/hoodset-app" target="_blank" rel="noreferrer">GitHub source & tests ${icon('share')}</a><a href="/chain/HoodsetVault.sol" target="_blank" rel="noreferrer">Vault Solidity source ${icon('share')}</a><a href="/chain/standard-input.json" target="_blank" rel="noreferrer">Reproducible compiler input ${icon('share')}</a><a href="/chain/vault.json" target="_blank" rel="noreferrer">ABI, bytecode & runtime hash ${icon('share')}</a><a href="https://docs.robinhood.com/chain/stock-tokens/" target="_blank" rel="noreferrer">RH Stock Token restrictions ${icon('share')}</a><a href="https://docs.openocean.finance/docs/swap-api/api-pricing-and-access" target="_blank" rel="noreferrer">OpenOcean access & fees ${icon('share')}</a></div></section><div class="archive-link"><div><b>Want to explore the paper model?</b><p>A separate sandbox with explicitly simulated balances and charts.</p></div><a class="btn" href="/paper.html">OPEN PAPER SANDBOX</a></div>`;
  }

  function searchResults(query='') {
    const q=query.trim().toLowerCase();
    const links=[...navItems.map(([id,label])=>({route:id,label,kind:'Workspace'})),...themes.map(t=>({route:'theme/'+t.id,label:t.name,kind:t.assets.join(' / ')}))].filter(x=>(x.label+' '+x.kind).toLowerCase().includes(q));
    return links.length?links.map(x=>btn(`<span><b>${esc(x.label)}</b><small>${esc(x.kind)}</small></span>`,'open-route','command-result',`data-route="${x.route}"`)).join(''):'<p class="command-empty">No matching page or allocation.</p>';
  }
  const searchDialog=()=>`<div class="command-search">${icon('search')}<input id="command-search" aria-label="Search pages and baskets" placeholder="Search pages, baskets or tickers" autocomplete="off"></div><div id="command-results">${searchResults()}</div><p class="footnote">Press Escape to close.</p>`;
  return { radarPage:()=>radarUI.render(true), shell, chart, themeCard, catalogue, discover, themePage, builder, draftPreview, importPanel, knownSets, onchain, portfolio, swapForm, tokens, sectors, watchlist, methodology, data, searchDialog, searchResults };
}
